    mes "^FF0000 Keys From 'F1'to 'F9'^000000are shortcut keys for ^0087FFeach item registered on Hot key window^000000."
    mes "^FF0000The Key 'F10'^000000adjusts^0087FFthe size of chat window^000000."
    next()
